import React, {useCallback, useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {RefreshControl, ScrollView, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import Body from './components/Body';
import Header from './components/Header';
import OverviewDocument from './components/OverviewDocument';
import Statistical from './components/Statistical';
import styles from './styles';
import {useAccountInfoServices} from '../../../hooks/apiHooks/useAccountInfoServices';
import {
  useCatalogService,
  useReceiptServices,
  useTicketServices,
} from '../../../hooks/apiHooks/useAPI';
import {useCatalogStore} from '../../../zutand/catalogStore';
import {useAppSelector} from '../../../hooks/useRedux';
import {useFocusEffect} from '@react-navigation/native';
import {useServiceStore} from '../../../zutand/servicesStore';
import Loading from '../../components/Loading';

export interface INumberReceipt {
  numberReceipt: number;
  numberNumberingReceipt: number;
  numberReceiptProcessing: number;
  numberReceiptReleased: number;
  numberReceiptFundSubmited: number;
  numberReceiptPendingFundSubmited: number;
}

const Home = () => {
  const {t} = useTranslation();
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [numberReceipt, setNumberReceipt] = useState<INumberReceipt>({
    numberReceipt: 0,
    numberNumberingReceipt: 0,
    numberReceiptProcessing: 0,
    numberReceiptReleased: 0,
    numberReceiptFundSubmited: 0,
    numberReceiptPendingFundSubmited: 0,
  });

  const {setListADJUSTMENT_CODE, setListALTERNATIVE_CODE} = useCatalogStore();

  const {
    setListServices,
    setListTicketByModelerId,
    setListAjustment,
    setListReplacement,
  } = useServiceStore();

  const AccountServices = useAccountInfoServices();
  const ReceiptService = useReceiptServices();
  const CatalogService = useCatalogService();

  const {dataAccount} = useAppSelector(state => state.account);
  const TicketService = useTicketServices();

  useEffect(() => {
    init();
  }, []);

  const init = async () => {
    try {
      setIsLoading(true);
      await Promise.all([
        handleInitData(),
        getInitCatalog(),
        handleInitService(),
      ]);
    } catch (error) {
    } finally {
      setIsLoading(false);
    }
  };

  const onRefreshData = () => {
    setIsRefreshing(true);
    handleInitData();
  };

  const getDashboardReport = async () => {
    const data = await ReceiptService.getDashboardReport();
    return data;
  };

  const getNumberReceipt = async () => {
    const data = await ReceiptService.getReceipt(0, 1);
    return data?.totalData;
  };

  const getNumberReceiptFundSubmited = async () => {
    const body = {
      q: '',
      terms: {
        requestStatus: ['fund_submitted'],
      },
    };
    const data = await ReceiptService.getReceipt(0, 1, body);
    return data?.totalData;
  };

  const getNumberReceiptPendingFundSubmited = async () => {
    const body = {
      q: '',
      terms: {
        requestStatus: ['pending_fund_submission'],
      },
    };
    const data = await ReceiptService.getReceipt(0, 1, body);
    return data?.totalData;
  };

  const handleInitData = async () => {
    try {
      const [
        numberReceipt,
        numberReceiptFundSubmited,
        numberReceiptPendingFundSubmited,
        dashboardReport,
      ] = await Promise.all([
        getNumberReceipt(),
        getNumberReceiptFundSubmited(),
        getNumberReceiptPendingFundSubmited(),
        getDashboardReport(),
      ]);

      setNumberReceipt({
        numberReceipt: numberReceipt || 0,
        numberNumberingReceipt: dashboardReport?.['error_receipt'] || 0,
        numberReceiptProcessing: dashboardReport?.['processing_receipt'] || 0,
        numberReceiptReleased: dashboardReport?.['released_receipt'] || 0,
        numberReceiptFundSubmited: numberReceiptFundSubmited || 0,
        numberReceiptPendingFundSubmited: numberReceiptPendingFundSubmited || 0,
      });
    } catch (error) {
    } finally {
      setIsRefreshing(false);
    }
  };

  const getInitCatalog = async () => {
    const [adjusment_code, alternative_code] = await Promise.all([
      CatalogService.getADJUSTMENT_CODE(),
      CatalogService.getALTERNATIVE_CODE(),
    ]);

    setListADJUSTMENT_CODE(adjusment_code);
    setListALTERNATIVE_CODE(alternative_code);
  };

  const getServiceOfTHADS = async (serviceCode: string) => {
    try {
      const roleIds = dataAccount?.roles?.map((r: any) => r.id).join(',');
      const body = {
        serviceCode: serviceCode,
        textSearch: null,
        roleIds: roleIds,
      };
      const params = {
        page: 0,
        size: 1000000,
      };
      const dataResp = await TicketService.getListServives(body, params);
      return dataResp?.content?.[0] || [];
    } catch (error) {
    } finally {
    }
  };

  const getServiceCode = async () => {
    const dataResp = await TicketService.getListServiceCode();
    if (dataResp) {
      const values = await Promise.all(
        dataResp?.map((item: any) =>
          getServiceOfTHADS(item['textField_input-2']),
        ),
      );
      return values;
    }
  };

  const getAdjustmentCode = async () => {
    const data = await CatalogService.getADJUSTMENT_RECEIPT_SERVICE();
    if (data) {
      const values = await Promise.all(
        data?.map((item: any) => getServiceOfTHADS(item['textField_input-2'])),
      );
      return values;
    }
  };

  const getReplacementCode = async () => {
    const data = await CatalogService.getREPLACEMENT_RECEIPT_SERVICE();
    if (data) {
      const values = await Promise.all(
        data?.map((item: any) => getServiceOfTHADS(item['textField_input-2'])),
      );
      return values;
    }
  };

  const handleInitService = async () => {
    const listModelerId = [];
    const listServiceCode = await getServiceCode();
    const listAdjustmentCode = await getAdjustmentCode();
    const listReplacementCode = await getReplacementCode();

    if (listServiceCode && listServiceCode?.length) {
      setListServices(listServiceCode?.filter((item: any) => item)?.flat());
      const listModeler = listServiceCode
        ?.filter((item: any) => item)
        ?.flat()
        ?.map((item: any) => item?.modelers)
        ?.flat();
      const listModelerIdService = listModeler?.map(
        (item: any) => item?.modelerId,
      );

      listModelerId.push(...listModelerIdService);
    }
    if (listAdjustmentCode && listAdjustmentCode?.length) {
      setListAjustment(listAdjustmentCode?.filter((item: any) => item)?.flat());
      const listModelerOfAdjustment = listAdjustmentCode
        ?.filter((item: any) => item)
        ?.flat()
        ?.map((item: any) => item?.modelers)
        ?.flat();
      const listModelerIdOfAdjustment = listModelerOfAdjustment?.map(
        (item: any) => item?.modelerId,
      );

      listModelerId.push(...listModelerIdOfAdjustment);
    }

    if (listReplacementCode && listReplacementCode?.length) {
      setListReplacement(
        listReplacementCode?.filter((item: any) => item)?.flat(),
      );
      const listModelerOfReplacement = listReplacementCode
        ?.filter((item: any) => item)
        ?.flat()
        ?.map((item: any) => item?.modelers)
        ?.flat();
      const listModelerIdOfReplacement = listModelerOfReplacement?.map(
        (item: any) => item?.modelerId,
      );
      listModelerId.push(...listModelerIdOfReplacement);
    }

    const uniqueModelerId = [...new Set(listModelerId?.filter(m => m))];

    const data = (await TicketService.getListTicketByListModelerId(
      uniqueModelerId,
    )) as any;
    if (data) {
      setListTicketByModelerId(data?.data);
    }
  };

  return (
    <SafeAreaView edges={[]} style={styles.ctnMain}>
      <Header />
      <ScrollView
        style={styles.mainContainer}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={onRefreshData} />
        }>
        {!isLoading && (
          <View style={styles.body}>
            <Body />
            <OverviewDocument numberReceipt={numberReceipt} />
            <Statistical numberReceipt={numberReceipt} />
          </View>
        )}

        {isLoading && <Loading message="Đang thực hiện lấy dữ liệu" />}
      </ScrollView>
    </SafeAreaView>
  );
};

export default Home;
