import {create} from 'zustand';
import {IServicesHome, Modeler} from '../app/screen/create-new/helper';

interface ServiceStore {
  listServices: IServicesHome[];
  listAjustment: IServicesHome[];
  listReplacement: IServicesHome[];
  listTicketByModelerId: Modeler[];
  setListServices: (listServices: IServicesHome[]) => void;
  setListAjustment: (listAjustment: IServicesHome[]) => void;
  setListTicketByModelerId: (listTicketByModelerId: Modeler[]) => void;
  setListReplacement: (listReplacement: IServicesHome[]) => void;
}

const initialSettingState = {
  listServices: [],
  listModeler: [],
  listTicketByModelerId: [],
  listAjustment: [],
  listReplacement: [],
};

export const useServiceStore = create<ServiceStore>((set, get) => ({
  ...initialSettingState,
  setListServices: (listServices: IServicesHome[]) => {
    set({listServices});
  },
  setListTicketByModelerId: (listTicketByModelerId: Modeler[]) => {
    set({listTicketByModelerId});
  },
  setListAjustment: (listAjustment: IServicesHome[]) => {
    set({listAjustment});
  },
  setListReplacement: (listReplacement: IServicesHome[]) => {
    set({listReplacement});
  },
}));
